import { vendorPrefix } from '@game-studio/utilities';
import { DeviceType } from './device-info/device-type';
import { DimensionCacheMap, IExtendedTouchEvent, IViewportDimensions } from './types';
import { VirtualKeyboard } from './virtual-keyboard';
import { DeviceOrientation } from './device-orientation';

const VENDOR_TRANSFORM = vendorPrefix.getProperty('transform');
const MEDIA_QUERY = '(-webkit-min-device-pixel-ratio: 1.5),\
                    (min--moz-device-pixel-ratio: 1.5),\
                    (-o-min-device-pixel-ratio: 3/2),\
                    (min-resolution: 1.5dppx)';

export class Viewport {

    private desktopDimensions: IViewportDimensions;
    private dimensionCache: DimensionCacheMap = new Map();
    public readonly isRetina: boolean;

    public constructor(private deviceType: DeviceType, private orientation: DeviceOrientation, private keyboard: VirtualKeyboard) {
        this.desktopDimensions = { width: window.innerWidth, height: window.innerHeight };
        this.isRetina = (window.devicePixelRatio > 1 || !!(window.matchMedia && window.matchMedia(MEDIA_QUERY).matches));
        this.keyboard.addListener('isOpen', this.onKeyboardOpen.bind(this));
        this.disableZoomGesture();

        if (this.keyboard.resizesWindowWhenOpen) {
            this.stopKeyboardResizingWindow();
        }
    }

    public get pixelRatio() {
        return Math.round(window.devicePixelRatio);
    }

    public get width() {
        if (this.deviceType.isDesktop) {
            return this.desktopDimensions.width;
        } else if (this.dimensionCache.has(this.orientation.value)) {
            // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
            return this.dimensionCache.get(this.orientation.value)!.width;
        }

        return window.innerWidth;
    }

    public get height() {
        if (this.deviceType.isDesktop) {
            return this.desktopDimensions.height;
        } else if (this.dimensionCache.has(this.orientation.value)) {
            // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
            return this.dimensionCache.get(this.orientation.value)!.height;
        }

        return window.innerHeight;
    }

    public get trueWidth() {
        return this.width * this.pixelRatio;
    }

    public get trueHeight() {
        return this.height * this.pixelRatio;
    }

    get safeAreas() {
        const divOne = document.createElement('div');
        const divTwo = document.createElement('div');

        divOne.style.width = divTwo.style.width = '0';
        divOne.style.height = divTwo.style.height = '0';
        divOne.style.paddingBottom = 'env(safe-area-inset-bottom)';
        divOne.style.paddingLeft = 'env(safe-area-inset-left)';
        divTwo.style.paddingRight = 'env(safe-area-inset-right)';
        divOne.style.visibility = 'hidden';
        document.body.appendChild(divOne);
        document.body.appendChild(divTwo);

        const boundsOne = divOne.getBoundingClientRect();
        const boundsTwo = divTwo.getBoundingClientRect();

        document.body.removeChild(divOne);
        document.body.removeChild(divTwo);

        return {
            left: boundsOne.width,
            bottom: boundsOne.height,
            right: boundsTwo.width
        };
    }

    public setDesktopDimensions(dimensions: IViewportDimensions) {
        this.desktopDimensions = dimensions;
    }

    public freezePageDimensions(isOpen: boolean) {
        if (this.keyboard.resizesWindowWhenOpen) {
            const page = this.getPage();

            if (isOpen) {
                page.style.width = `${window.innerWidth}px`;
                page.style.height = `${window.innerHeight - this.keyboard.height}px`;
            } else {
                page.style.width = '';
                page.style.height = '';
            }
        }
    }

    public autoScale(element: HTMLElement, config: IViewportDimensions, isFromResizeEvent: boolean = false) {
        const multiplier = config.doubleResolution ? 2 : 1;
        const configWidth = config.width * multiplier;
        const configHeight = config.height * multiplier;

        element.style.width = `${configWidth}px`;
        element.style.height = `${configHeight}px`;

        const windowWidth = window.innerWidth;
        const windowHeight = window.innerHeight;
        const widthScale = windowWidth / configWidth;
        const heightScale = windowHeight / configHeight;
        const smallestScale = Math.round(40 * Math.min(widthScale, heightScale)) / 40;
        const leftPosition = Math.floor((windowWidth - (configWidth * smallestScale)) / 2);
        const topPosition = Math.floor((windowHeight - (configHeight * smallestScale)) / 2);

        element.style[VENDOR_TRANSFORM as any] = `scale(${smallestScale})`;
        element.style.transform = `scale(${smallestScale})`;
        element.style.left = `${leftPosition}px`;
        element.style.top = `${topPosition}px`;

        if (!isFromResizeEvent) {
            window.addEventListener('resize', () => this.autoScale(element, config, true));
        }
    }

    public disableZoomGesture() {
        document.addEventListener('touchmove', (event: TouchEvent) => {
            const extendedEvent = event as IExtendedTouchEvent;
            if (extendedEvent.scale !== undefined && extendedEvent.scale !== 1) {
                event.preventDefault();
            }
        }, { passive: false });
    }

    private getPage(): HTMLElement {
        return document.body.firstElementChild as HTMLElement;
    }

    private stopKeyboardResizingWindow() {
        this.keyboard.addListener('isOpen', this.freezePageDimensions.bind(this));
        this.orientation.addListener('onOrientationStateChanged', () => this.freezePageDimensions(false));
    }

    private onKeyboardOpen(isOpen: boolean) {
        if (!isOpen) {
            return;
        }
        if (!this.dimensionCache.has(this.orientation.value)) {
            this.dimensionCache.set(this.orientation.value, {
                width: window.innerWidth,
                height: window.innerHeight
            });
        }
    }
}